fn levenshtein(s1: Text, s2: Text) -> Int {
    let m: Int = string_len(s1);
    let n: Int = string_len(s2);
    let cols: Int = n + 1;
    let rows: Int = m + 1;
    let total: Int = rows * cols;

    let dp: Int[] = [];
    loop i in 0..total {
        dp = dp + [0];
    }

    loop i in 0..rows {
        dp[i * cols] = i;
    }

    loop j in 0..cols {
        dp[j] = j;
    }

    loop i in 1..rows {
        loop j in 1..cols {
            let c1: Text = copy(s1, i, 1);
            let c2: Text = copy(s2, j, 1);
            let cost: Int = 0;
            if !string_eq(c1, c2) {
                cost = 1;
            }
            let del: Int = dp[(i - 1) * cols + j] + 1;
            let ins: Int = dp[i * cols + (j - 1)] + 1;
            let sub: Int = dp[(i - 1) * cols + (j - 1)] + cost;

            let best: Int = del;
            if ins < best { best = ins; }
            if sub < best { best = sub; }

            dp[i * cols + j] = best;
        }
    }

    ret dp[m * cols + n];
}

